  'Tanaka: office supplies': { n: '田中：文房具投げ', tail: '', note: '素の田中は遠くから：↓＋Uでペン、↓＋Jでホッチキス、空中でIを押すとマグカップを落とす。' },
  'Angel: double juggle': { n: '天使：二段打ち上げ', tail: '', note: '←←＋Iで天使を呼び、↓＋Iで打ち上げ、U、U、Iで再び打ち上げ、Kで締め。' },
  'Angel: triple juggle': { n: '天使：三段打ち上げ', tail: '', note: '天使憑依なら3回浮かせられる：↓＋I、U、U、Iで再び浮かせ、もう一度U、U、I、そしてK。' },
