  'Kuro: Full Moon Tempest': { n: 'クロ：満月の嵐', tail: '', note: '←→＋I：満月の嵐。背の高いゆっくりした三日月で、ジャンプでかわせず、しゃがみガードにも当たる。' },
  'Kuro: Moon Tempest': { n: 'クロ：月の嵐', tail: '', note: '←→＋U：月の嵐。影の三日月が床を走る（中段：ジャンプでかわせる）。ダウンを奪う。' },
  'Mei charge: Rising Cudgel': { n: 'メイの溜め技：昇り棍', tail: '', note: 'Iを0.5秒押し続けて（気が集まる）離す：昇り棍。棍を振り上げて浮かせる。空中追撃へ。' },
  'Mei charge: Typhoon Swing': { n: 'メイの溜め技：台風振り', tail: '', note: 'Iを1秒以上押し続ける：台風振り。回転する大振りで吹き飛ばす。' },
  'Lyra charge: Rising Glyph': { n: 'ライラの溜め技：昇る紋', tail: '', note: 'Iを0.5秒押し続けて（気が集まる）離す：昇る紋。どこにいても足元の紋で浮かせる。空中追撃へ。' },
  'Lyra charge: Nova Glyph': { n: 'ライラの溜め技：新星の紋', tail: '', note: 'Iを1秒以上押し続ける：新星の紋。巨大な星の紋で吹き飛ばす。' },
  'Kappa charge: Ambush': { n: 'カッパの溜め技：奇襲', tail: '', note: 'Iを0.5秒押し続けて（気が集まる）離す：奇襲。短い溜め：低く飛び込んで爪で浮かせる。空中追撃へ。' },
  'Kappa charge: Dish Storm': { n: 'カッパの溜め技：皿の嵐', tail: '', note: 'Iを1秒以上押し続ける：皿の嵐。長い溜め：皿を次々と投げ、最後の一枚で吹き飛ばす。' },
  'Jesse charge: point-blank Thunder Shot': { n: 'ジェシーの溜め撃ち：至近距離サンダーショット', tail: 'サンダーショット、追い撃ち、二丁追い撃ち、六連発フィナーレ', note: '至近距離でIを最大まで溜める：サンダーショットがダウンではなく打ち上げになり、射撃の空中追撃へ。のけぞって上を狙う。' },
  'Jesse charge: Thunder Shot': { n: 'ジェシーの溜め撃ち：サンダーショット', tail: '', note: 'Iを押し続けると銃に力が溜まる（0.4秒で中、0.9秒で最大）。最大で離すと、貫通する巨大な一発「サンダーショット」。' },
  'Jesse charge: Buffalo Blast': { n: 'ジェシーの溜め撃ち：バッファローブラスト', tail: 'ブラスト、追い撃ち、二丁追い撃ち、とどめの一発', note: 'Kを最大まで溜める：巨大な散弾3発で宙に浮かせ、射撃の空中追撃へ。' },
  'Jesse charge: Dead-Eye': { n: 'ジェシーの溜め撃ち：デッドアイ', tail: '', note: '→→+Iを押し続ける：照準が合い、画面を貫く「デッドアイショット」。' },
  'Kuro mid-air: juggle': { n: 'クロの空中技：追撃', tail: '昇りクナイ斬り、双クナイ、影分身昇り、影斬り', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（昇りクナイ斬り、双クナイ、影分身昇り、影斬り）。' },
  'Kuro mid-air: jumping': { n: 'クロの空中技：ジャンプ', tail: '空中クナイ斬り、空中逆斬り、クナイの雨、影車', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中クナイ斬り、空中逆斬り、クナイの雨、影車）。' },
  'Tetsu mid-air: juggle': { n: 'テツの空中技：追撃', tail: '双掌上げ、鉄槌、気の間欠泉掌、雷掌', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（双掌上げ、鉄槌、気の間欠泉掌、雷掌）。' },
  'Tetsu mid-air: jumping': { n: 'テツの空中技：ジャンプ', tail: '空中掌、空中肘、百裂拳、落山', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中掌、空中肘、百裂拳、落山）。' },
  'Mei mid-air: juggle': { n: 'メイの空中技：追撃', tail: '突き上げ、振り上げ、風車昇り、雲の棍叩き', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（突き上げ、振り上げ、風車昇り、雲の棍叩き）。' },
  'Mei mid-air: jumping': { n: 'メイの空中技：ジャンプ', tail: '空中突き、空中振り、空中連打、金の風車', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中突き、空中振り、空中連打、金の風車）。' },
  'Lyra mid-air: juggle': { n: 'ライラの空中技：追撃', tail: '持ち上げの紋、水晶の雨、星の柱、三角の爆発', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（持ち上げの紋、水晶の雨、星の柱、三角の爆発）。' },
  'Lyra mid-air: jumping': { n: 'ライラの空中技：ジャンプ', tail: '空中の紋、空中水晶、破片の連射、軌道の爆発', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中の紋、空中水晶、破片の連射、軌道の爆発）。' },
  'Aldric mid-air: juggle': { n: 'アルドリックの空中技：追撃', tail: '盾持ち上げ、剣上げ、昇天、裁きの十字', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（盾持ち上げ、剣上げ、昇天、裁きの十字）。' },
  'Aldric mid-air: jumping': { n: 'アルドリックの空中技：ジャンプ', tail: '空中斬り、空中盾打ち、剣輪連撃、急降下の光', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中斬り、空中盾打ち、剣輪連撃、急降下の光）。' },
  'Kappa mid-air: juggle': { n: 'カッパの空中技：追撃', tail: 'かき上げ、くちばし突き、間欠泉ジャンプ、甲羅砲弾', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（かき上げ、くちばし突き、間欠泉ジャンプ、甲羅砲弾）。' },
  'Kappa mid-air: jumping': { n: 'カッパの空中技：ジャンプ', tail: '空中かき、空中つつき、雨の爪、滝下り', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中かき、空中つつき、雨の爪、滝下り）。' },
  'Jesse mid-air: juggle': { n: 'ジェシーの空中技：追撃', tail: '追い撃ち、二丁追い撃ち、コイン撃ち、六連発フィナーレ', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（追い撃ち、二丁追い撃ち、コイン撃ち、六連発フィナーレ）。' },
  'Jesse mid-air: jumping': { n: 'ジェシーの空中技：ジャンプ', tail: '空中射撃、空中二丁撃ち、空中ファニング、急降下連射', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中射撃、空中二丁撃ち、空中ファニング、急降下連射）。' },
  'Tanaka mid-air: juggle': { n: '田中の空中技：追撃', tail: 'カバン上げ、ネクタイ鞭、エレベーターアッパー、書類嵐キック', note: '↓+Iで打ち上げ、空中追撃でU、U、Iで再打ち上げ、Kで締め。地上の連続技とは違う空中版（カバン上げ、ネクタイ鞭、エレベーターアッパー、書類嵐キック）。' },
  'Tanaka mid-air: jumping': { n: '田中の空中技：ジャンプ', tail: '空中カバン、空中ネクタイ、空中書類嵐、カバン隕石', note: '↓+Iで打ち上げ、W で追ってジャンプし、空中でU、U、I、K（空中カバン、空中ネクタイ、空中書類嵐、カバン隕石）。' },
  'Kuro string: U, U, K': { n: 'クロの連続技：U、U、K', tail: '', note: 'U、Uのあと K：三日月落とし。' },
