  'Tetsu string: U, U, K': { n: 'テツの連続技：U、U、K', tail: '', note: 'U、Uのあと K：山割り。' },
  'Mei string: U, U, K': { n: 'メイの連続技：U、U、K', tail: '', note: 'U、Uのあと K：金箍棒落とし。' },
  'Lyra string: U, U, K': { n: 'ライラの連続技：U、U、K', tail: '', note: 'U、Uのあと K：星座の爆発。' },
